                int sheetRow = i + 1;
                PlayerMetaData data = new PlayerMetaData();
                bool rowOk = true;

                // Id (int)
                try { data.Id = ParseInt(cells[0]); }
                catch (Exception e)
                {
                    Console.Error.WriteLine("[SpecDataManager] [Player] 파싱 오류\n" +
                        "  위치: 시트 행 " + sheetRow + ", 열 1 (Id)\n" +
                        "  타입: int\n" +
                        "  값: \"" + cells[0] + "\"\n" +
                        "  원인: " + e.Message);
                    rowOk = false;
                }

                if (rowOk)
                {
                    _playerDict[data.Id] = data;
                    _playerList.Add(data);
                }
                else
                {
                    Console.Error.WriteLine("[SpecDataManager] [Player] 행 " + sheetRow + " 파싱 오류로 스킵됨.");
                }
            }
            Console.WriteLine("[SpecDataManager] Player 로드 완료: " + _playerList.Count + "개");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("[SpecDataManager] Player 다운로드 실패: " + ex.Message);
        }
    }

